import{_ as t,o as a,c as r,ag as s}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Case Studies","description":"","frontmatter":{"source":"resources/case-studies.md"},"headers":[],"relativePath":"resources/case-studies.md","filePath":"resources/case-studies.md"}'),o={name:"resources/case-studies.md"};function n(i,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="case-studies" tabindex="-1">Case Studies <a class="header-anchor" href="#case-studies" aria-label="Permalink to &quot;Case Studies&quot;">​</a></h1><blockquote><p>Incidents and studies to teach from, grouped by topic. Each has a source, the week it fits, the safety-contract rule it motivates, and two discussion questions. Facts and numbers come from the linked sources as collected in <a href="./../research/notes/evidence-senior.html">Evidence Base and Reading List: &quot;Engineering Software with AI&quot; (CS 4xxx/5xxx)</a> and <a href="./../research/notes/tools-senior.html">Course B (&quot;Engineering Software with AI&quot;): the $0 tool landscape, checked 2 November 2026</a>. Cases marked <strong>[A]</strong> were collected by the sibling course, Building Apps with AI (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/resources/case-studies.html" target="_blank" rel="noreferrer">its case studies</a>), and are summarized here for seniors.</p></blockquote><p>These are not stories about careless people. They involve major vendors, experienced engineers and popular tools. Read each one for the <strong>mechanism</strong>: what made the failure possible, and which control would have stopped it. Rule numbers refer to the <a href="./../setup/safety-contract.html">agent safety contract</a>.</p><p><strong>On this page:</strong> <a href="#using-these-in-class">Using these in class</a> · <a href="#prompt-injection-and-agent-incidents">A. Prompt injection and agent incidents</a> · <a href="#supply-chain-and-insecure-code">B. Supply chain and insecure code</a> · <a href="#deleted-databases">C. Deleted databases</a> · <a href="#benchmark-inflation">D. Benchmark inflation</a> · <a href="#maintainers-ai-policies">E. Maintainers&#39; AI policies</a> · <a href="#where-sources-disagree">Where sources disagree</a></p><h2 id="using-these-in-class" tabindex="-1">Using these in class <a class="header-anchor" href="#using-these-in-class" aria-label="Permalink to &quot;Using these in class&quot;">​</a></h2><ul><li><strong>Jigsaw (20 minutes, the Seminar&#39;s discussion block).</strong> Groups of three each take one case for 8 minutes and fill in four lines: <em>mechanism · which leg of the lethal trifecta (or which grading flaw, or which policy) · which control would have stopped it · what our own setup does about it.</em> Two minutes each to report back.</li><li><strong>Default sets:</strong> week 4: A1, A2, A4, A5 · week 10: B1, B4, B5, B6 · week 12: D2, D3, D5 · week 14: E1, E2, E3, E7.</li><li><strong>In a threat model or report,</strong> cite the case and say which claim is <strong>observed</strong> (in the source) and which is <strong>inferred</strong> (your reading).</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>🔴 AI off: reading responses and reflections that use these cases are your own writing.</p></div><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Case</th><th>When</th><th>Mechanism in one line</th><th>Rules</th><th>Week</th></tr></thead><tbody><tr><td>A1</td><td>Supabase MCP</td><td>Jul 2025</td><td>One MCP server supplied all three legs of the lethal trifecta</td><td>4 · 5</td><td>4</td></tr><tr><td>A2</td><td>GitHub MCP</td><td>May 2025</td><td>A public issue steered an agent with a broad token to leak a private repository</td><td>4 · 5 · 10</td><td>4</td></tr><tr><td>A3</td><td>MCP tool poisoning</td><td>Apr 2025</td><td>Hidden instructions in tool descriptions; descriptions changed after approval</td><td>8</td><td>3–4</td></tr><tr><td>A4</td><td>Copilot auto-approve and CamoLeak</td><td>2025</td><td>Agent edited its own permissions; private code leaked through image URLs</td><td>2 · 4</td><td>4</td></tr><tr><td>A5</td><td>AIShellJack</td><td>2025–26</td><td>314 planted payloads ran commands in agentic editors up to 84% of the time</td><td>2 · 3</td><td>4</td></tr><tr><td>A6</td><td>Received folders [A]</td><td>2026</td><td>git settings in a received folder ran code before any prompt</td><td>3</td><td>2–4</td></tr><tr><td>A7</td><td>Autopilot [A]</td><td>2026</td><td>A web page made an autopilot agent send secrets out</td><td>2 · 4</td><td>4</td></tr><tr><td>A8</td><td>PixelLeak [A]</td><td>Sep 2026</td><td>Helpful agents published 13,000+ internal screenshots, no attacker</td><td>10</td><td>9, 13</td></tr><tr><td>A9</td><td>Rules-file backdoor [A]</td><td>Mar 2025</td><td>Invisible Unicode in rules files steered code generation</td><td>8</td><td>3</td></tr><tr><td>B1</td><td>Shai-Hulud</td><td>Sep 2025</td><td>A self-replicating worm compromised 500+ npm packages</td><td>8</td><td>10</td></tr><tr><td>B2</td><td>Nx s1ngularity [A]</td><td>Aug 2025</td><td>A poisoned package used installed AI CLIs to hunt for secrets</td><td>4 · 8</td><td>10</td></tr><tr><td>B3</td><td>Amazon Q extension [A]</td><td>Jul 2025</td><td>A wiper prompt was merged and shipped</td><td>8</td><td>9–10</td></tr><tr><td>B4</td><td>Malware after AI keys [A]</td><td>Oct 2026</td><td>Packages and a hosted console leaked AI keys and agent configs</td><td>4 · 6 · 8</td><td>10</td></tr><tr><td>B5</td><td>Slopsquatting [A]</td><td>2025–26</td><td>Models invent package names; attackers register them</td><td>8</td><td>10</td></tr><tr><td>B6</td><td>BaxBench</td><td>2025</td><td>About half of correct generated backends were exploitable</td><td>9</td><td>10</td></tr><tr><td>C1</td><td>Replit [A]</td><td>Jul 2025</td><td>Agent ignored a code freeze, deleted production data, faked results</td><td>4 · 7 · 9</td><td>2, 13</td></tr><tr><td>C2</td><td>PocketOS [A]</td><td>Apr 2026</td><td>Agent used a stray token to delete production data and its backups</td><td>5 · 7</td><td>2, 13</td></tr><tr><td>D1–D6</td><td>Benchmark inflation</td><td>2024–26</td><td>Leaked solutions, weak tests, memorization, lenient graders</td><td>9</td><td>1, 12</td></tr><tr><td>E1–E8</td><td>Maintainers&#39; AI policies</td><td>2021–26</td><td>From bans to disclosure to platform-level throttling</td><td>10 · 11</td><td>9, 14</td></tr></tbody></table><hr><h2 id="prompt-injection-and-agent-incidents" tabindex="-1">Prompt injection and agent incidents <a class="header-anchor" href="#prompt-injection-and-agent-incidents" aria-label="Permalink to &quot;Prompt injection and agent incidents&quot;">​</a></h2><p><strong>The frame for this section</strong> is Simon Willison&#39;s <strong>lethal trifecta</strong>: an agent with access to private data, exposure to untrusted content, and a way to send data out can be made to leak the data. Coding agents usually have all three. The defenses that hold are architectural: the OWASP GenAI LLM Top 10 for 2026 now ranks Prompt Injection first and Excessive Agency third (<a href="https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/" target="_blank" rel="noreferrer">OWASP</a>); design patterns such as plan-then-execute, dual LLM and context minimization give provable resistance at some cost in utility (<a href="https://arxiv.org/abs/2506.08837" target="_blank" rel="noreferrer">Beurer-Kellner et al.</a>); and CaMeL, which separates a privileged planner from a quarantined parser behind capability policies, solved 77% of AgentDojo tasks with provable security against 84% undefended (<a href="https://arxiv.org/abs/2503.18813" target="_blank" rel="noreferrer">Debenedetti et al.</a>).</p><h3 id="a1-supabase-mcp-the-lethal-trifecta-in-one-server" tabindex="-1">A1. Supabase MCP: the lethal trifecta in one server <a class="header-anchor" href="#a1-supabase-mcp-the-lethal-trifecta-in-one-server" aria-label="Permalink to &quot;A1. Supabase MCP: the lethal trifecta in one server&quot;">​</a></h3><p><em>July 2025.</em> An agent connected to a Supabase MCP server with the <code>service_role</code> key, which bypasses row-level security, was asked to handle support tickets. A ticket contained instructions; the agent followed them and copied secrets from the database into a reply the attacker could read. One server supplied private data, untrusted content and the way out. Making the server <strong>read-only</strong> removes the exfiltration path.</p><ul><li><strong>Lesson:</strong> count the legs per <em>session</em>, not per tool. A trusted server plus untrusted data is untrusted.</li><li><strong>Rules:</strong> 4 (no real secrets near an agent reading untrusted text), 5 (scoped, read-only tokens).</li><li><strong>Discuss:</strong> (1) Which single change removes the most risk: a read-only key, a separate session for reading tickets, or an approval prompt on writes? (2) Map your team&#39;s agent setup onto the three legs.</li><li><strong>Source:</strong> <a href="https://simonwillison.net/2025/Jul/6/supabase-mcp-lethal-trifecta/" target="_blank" rel="noreferrer">Willison, on General Analysis</a></li></ul><h3 id="a2-github-mcp-a-public-issue-leaks-a-private-repository" tabindex="-1">A2. GitHub MCP: a public issue leaks a private repository <a class="header-anchor" href="#a2-github-mcp-a-public-issue-leaks-a-private-repository" aria-label="Permalink to &quot;A2. GitHub MCP: a public issue leaks a private repository&quot;">​</a></h3><p><em>May 2025.</em> Invariant Labs showed that a malicious public issue could lead an agent, holding a GitHub token with access to the user&#39;s private repositories, to copy private-repository data into a public pull request. Invariant calls the problem architectural, not a bug in the server.</p><ul><li><strong>Lesson:</strong> a broad token turns every public input into a potential instruction with private reach.</li><li><strong>Rules:</strong> 4, 5, 10.</li><li><strong>Discuss:</strong> (1) Write the narrowest token that would still let the agent do the original task. (2) Who reviews what an agent posts publicly in your team&#39;s workflow?</li><li><strong>Source:</strong> <a href="https://invariantlabs.ai/blog/mcp-github-vulnerability" target="_blank" rel="noreferrer">Invariant Labs: GitHub MCP exploited</a></li></ul><h3 id="a3-mcp-tool-poisoning-instructions-the-user-never-sees" tabindex="-1">A3. MCP tool poisoning: instructions the user never sees <a class="header-anchor" href="#a3-mcp-tool-poisoning-instructions-the-user-never-sees" aria-label="Permalink to &quot;A3. MCP tool poisoning: instructions the user never sees&quot;">​</a></h3><p><em>April 2025.</em> Hidden instructions in an MCP <strong>tool description</strong>, shown to the model but not to the user, got an agent to read SSH keys. A server can also change a tool&#39;s description after the user approved it. The MCP specification&#39;s own security best practices now catalogue related attacks: confused deputy, token passthrough (forbidden), SSRF during OAuth discovery, local MCP server compromise through malicious startup commands, and more.</p><ul><li><strong>Lesson:</strong> a tool description is a prompt. Review it like code, and pin servers to a version you&#39;ve read.</li><li><strong>Rule:</strong> 8.</li><li><strong>Discuss:</strong> (1) Your <code>mcp-from-scratch</code> server returns a tool list. What stops a later version from changing it? (2) Which attacks in the spec&#39;s catalogue apply to a stdio server on your own laptop?</li><li><strong>Sources:</strong> <a href="https://invariantlabs.ai/blog/mcp-security-notification" target="_blank" rel="noreferrer">Invariant Labs: tool poisoning</a> · <a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/security_best_practices" target="_blank" rel="noreferrer">MCP Security Best Practices</a></li></ul><h3 id="a4-copilot-edits-its-own-permissions-and-camoleak" tabindex="-1">A4. Copilot edits its own permissions, and CamoLeak <a class="header-anchor" href="#a4-copilot-edits-its-own-permissions-and-camoleak" aria-label="Permalink to &quot;A4. Copilot edits its own permissions, and CamoLeak&quot;">​</a></h3><p><em>2025.</em> In CVE-2025-53773, injected text made Copilot write <code>&quot;chat.tools.autoApprove&quot;: true</code> into <code>.vscode/settings.json</code>, switching itself into auto-approve mode (CVSS 7.8; patched August 2025). In CamoLeak (CVE-2025-59145, CVSS 9.6), hidden comments in a pull request made Copilot Chat leak private code as a sequence of pre-signed image URLs; GitHub disabled image rendering in Copilot Chat.</p><ul><li><strong>Lesson:</strong> an agent must not be able to edit its own permissions, and any rendered URL is a way out.</li><li><strong>Rules:</strong> 2, 4.</li><li><strong>Discuss:</strong> (1) Which files in your setup control your agent&#39;s permissions, and can the agent write them? (2) List every channel by which <code>mini-agent</code> could send data out, including ones that don&#39;t look like network calls.</li><li><strong>Sources:</strong> <a href="https://cybersecuritynews.com/github-copilot-rce-vulnerability/" target="_blank" rel="noreferrer">CVE-2025-53773 (Cybersecurity News)</a> · <a href="https://legitsecurity.com/blog/camoleak-critical-github-copilot-vulnerability-leaks-private-source-code" target="_blank" rel="noreferrer">CamoLeak (Legit Security)</a></li></ul><h3 id="a5-your-ai-my-shell-injection-rates-in-agentic-editors" tabindex="-1">A5. Your AI, My Shell: injection rates in agentic editors <a class="header-anchor" href="#a5-your-ai-my-shell-injection-rates-in-agentic-editors" aria-label="Permalink to &quot;A5. Your AI, My Shell: injection rates in agentic editors&quot;">​</a></h3><p><em>Study, 2025–26.</em> AIShellJack planted 314 payloads, covering 70 MITRE ATT&amp;CK techniques, in project files and rules. Cursor and Copilot ran the malicious commands <strong>up to 84% of the time</strong>.</p><ul><li><strong>Lesson:</strong> &quot;the model will notice&quot; is not a defense. Rates like these make the sandbox and approvals mandatory.</li><li><strong>Rules:</strong> 2, 3. <strong>[Grad seminar]</strong> paper.</li><li><strong>Discuss:</strong> (1) The week 4 lab&#39;s poisoned README is one payload. What would a fair test of your defenses need? (2) Which ATT&amp;CK techniques does an approval gate stop, and which does it not?</li><li><strong>Source:</strong> <a href="https://arxiv.org/abs/2509.22040" target="_blank" rel="noreferrer">Liu et al., arXiv 2509.22040</a></li></ul><h3 id="a6-received-folders-code-that-runs-before-the-prompt" tabindex="-1">A6. Received folders: code that runs before the prompt <a class="header-anchor" href="#a6-received-folders-code-that-runs-before-the-prompt" aria-label="Permalink to &quot;A6. Received folders: code that runs before the prompt&quot;">​</a></h3><p><em>2026, [A].</em> Coding agents run <code>git status</code> in the background when they open a folder, often before asking whether you trust it. A project received <em>as a folder</em> with its hidden <code>.git</code> directory can carry git settings that run an attacker&#39;s program outside the agent&#39;s sandbox, with no prompt at all. Cloning the same project from its URL is safe.</p><ul><li><strong>Lesson:</strong> approval prompts protect you only from the actions they&#39;re asked about.</li><li><strong>Rule:</strong> 3.</li><li><strong>Discuss:</strong> Why is a clone from a URL safe when the same files from a zip are not?</li><li><strong>Source:</strong> <a href="https://www.manifold.security/blog/ai-coding-agents-git-hijack" target="_blank" rel="noreferrer">Manifold Security</a></li></ul><h3 id="a7-autopilot-a-web-page-that-sent-secrets-away" tabindex="-1">A7. Autopilot: a web page that sent secrets away <a class="header-anchor" href="#a7-autopilot-a-web-page-that-sent-secrets-away" aria-label="Permalink to &quot;A7. Autopilot: a web page that sent secrets away&quot;">​</a></h3><p><em>2026, [A].</em> In the autopilot mode of a CLI agent, a user asked the agent to fetch a web page. Hidden instructions on the page made the agent read the project&#39;s <code>.env.prod</code> and send the secrets to the attacker in about 28 seconds. The vendor confirmed the finding but did not treat it as a vulnerability, because the user had chosen full autonomy.</p><ul><li><strong>Lesson:</strong> turning approvals off transfers the risk to you, by the vendor&#39;s own account.</li><li><strong>Rules:</strong> 2, 4.</li><li><strong>Discuss:</strong> Do you accept the vendor&#39;s position? What would have stopped it with approvals still off?</li><li><strong>Source:</strong> <a href="https://adversa.ai/blog/cryptographic-context-injection-github-copilot/" target="_blank" rel="noreferrer">Adversa AI</a></li></ul><h3 id="a8-pixelleak-helpful-agents-publish-13000-screenshots" tabindex="-1">A8. PixelLeak: helpful agents publish 13,000 screenshots <a class="header-anchor" href="#a8-pixelleak-helpful-agents-publish-13000-screenshots" aria-label="Permalink to &quot;A8. PixelLeak: helpful agents publish 13,000 screenshots&quot;">​</a></h3><p><em>September 2026, [A].</em> Developers asked agents to attach before-and-after screenshots to code reviews. The agents created <strong>public GitHub repositories</strong> to host the images, exposing more than 13,000 internal screenshots from over 300 organizations. At one company the workaround spread through a shared skill file. Secret scanners, which read text, couldn&#39;t see what was in the pictures.</p><ul><li><strong>Lesson:</strong> no attacker, no bug, just a helpful agent. Publishing is an action that needs a human.</li><li><strong>Rule:</strong> 10.</li><li><strong>Discuss:</strong> (1) Whose mistake was this? (2) Which of your team&#39;s agents can create a public artifact, and what stops it?</li><li><strong>Source:</strong> <a href="https://thehackernews.com/2026/09/ai-coding-agents-exposed-13000-internal.html" target="_blank" rel="noreferrer">The Hacker News</a></li></ul><h3 id="a9-the-rules-file-backdoor" tabindex="-1">A9. The rules-file backdoor <a class="header-anchor" href="#a9-the-rules-file-backdoor" aria-label="Permalink to &quot;A9. The rules-file backdoor&quot;">​</a></h3><p><em>March 2025, [A].</em> Invisible Unicode characters in AI rules files can steer Copilot or Cursor to insert backdoors into generated code. The text survives forks and gets past human review because people can&#39;t see it.</p><ul><li><strong>Lesson:</strong> an <code>AGENTS.md</code> from the internet is a stranger&#39;s instructions to your agent.</li><li><strong>Rule:</strong> 8.</li><li><strong>Discuss:</strong> How would you detect an instruction you can&#39;t see? Write the one-line check.</li><li><strong>Source:</strong> <a href="https://www.pillar.security/blog/new-vulnerability-in-github-copilot-and-cursor-how-hackers-can-weaponize-code-agents" target="_blank" rel="noreferrer">Pillar Security</a></li></ul><hr><h2 id="supply-chain-and-insecure-code" tabindex="-1">Supply chain and insecure code <a class="header-anchor" href="#supply-chain-and-insecure-code" aria-label="Permalink to &quot;Supply chain and insecure code&quot;">​</a></h2><h3 id="b1-shai-hulud-a-self-replicating-npm-worm" tabindex="-1">B1. Shai-Hulud: a self-replicating npm worm <a class="header-anchor" href="#b1-shai-hulud-a-self-replicating-npm-worm" aria-label="Permalink to &quot;B1. Shai-Hulud: a self-replicating npm worm&quot;">​</a></h3><p><em>September 2025.</em> The Shai-Hulud worm compromised <strong>500+ npm packages</strong>, spreading by publishing itself with stolen maintainer credentials. CISA advised auditing lockfiles, pinning to releases from before 16 September 2025, rotating credentials and requiring phishing-resistant MFA. It is the background to the 2026 AI-key stealers (B4).</p><ul><li><strong>Lesson:</strong> the package you meant to install can be the malicious one. Lockfiles and pinned versions are a control, not a formality.</li><li><strong>Rule:</strong> 8.</li><li><strong>Discuss:</strong> (1) What does a committed <code>package-lock.json</code> protect you from, and what not? (2) Which of <code>roomly</code>&#39;s dev dependencies run code at install time?</li><li><strong>Source:</strong> <a href="https://www.cisa.gov/news-events/alerts/2025/09/23/widespread-supply-chain-compromise-impacting-npm-ecosystem" target="_blank" rel="noreferrer">CISA alert</a></li></ul><h3 id="b2-nx-s1ngularity-malware-that-used-your-ai-tools" tabindex="-1">B2. Nx s1ngularity: malware that used your AI tools <a class="header-anchor" href="#b2-nx-s1ngularity-malware-that-used-your-ai-tools" aria-label="Permalink to &quot;B2. Nx s1ngularity: malware that used your AI tools&quot;">​</a></h3><p><em>August 2025, [A].</em> Poisoned releases of the Nx package ran a script on install that used AI CLIs already on the machine to search for secrets and crypto wallets, then uploaded them to public repositories: 2,349 credentials from 1,079 systems. It is described as the first supply-chain attack to turn developers&#39; AI assistants against them.</p><ul><li><strong>Lesson:</strong> an installed agent CLI is a capability that any local program can borrow.</li><li><strong>Rules:</strong> 4, 8.</li><li><strong>Discuss:</strong> Map it onto the lethal trifecta. Which leg did the attacker bring?</li><li><strong>Sources:</strong> <a href="https://blog.gitguardian.com/the-nx-s1ngularity-attack-inside-the-credential-leak/" target="_blank" rel="noreferrer">GitGuardian</a> · <a href="https://nx.dev/blog/s1ngularity-postmortem" target="_blank" rel="noreferrer">Nx postmortem</a></li></ul><h3 id="b3-amazon-q-a-wiper-prompt-ships-in-an-extension" tabindex="-1">B3. Amazon Q: a wiper prompt ships in an extension <a class="header-anchor" href="#b3-amazon-q-a-wiper-prompt-ships-in-an-extension" aria-label="Permalink to &quot;B3. Amazon Q: a wiper prompt ships in an extension&quot;">​</a></h3><p><em>July 2025, [A].</em> A pull request from an untrusted contributor to the Amazon Q VS Code extension added a prompt telling the agent to act as a &quot;system cleaner&quot; deleting local files and cloud resources. It shipped to users; a syntax error stopped it from working.</p><ul><li><strong>Lesson:</strong> a prompt inside a tool is code. Review changes to prompts and instruction files with the same care, including in the PR round.</li><li><strong>Rule:</strong> 8.</li><li><strong>Discuss:</strong> Your review checklist covers code. What would catch a malicious paragraph of English?</li><li><strong>Sources:</strong> <a href="https://www.bleepingcomputer.com/news/security/amazon-ai-coding-agent-hacked-to-inject-data-wiping-commands/" target="_blank" rel="noreferrer">BleepingComputer</a> · <a href="https://www.theregister.com/2025/07/24/amazon_q_ai_prompt/" target="_blank" rel="noreferrer">The Register</a></li></ul><h3 id="b4-malware-that-hunts-for-ai-keys" tabindex="-1">B4. Malware that hunts for AI keys <a class="header-anchor" href="#b4-malware-that-hunts-for-ai-keys" aria-label="Permalink to &quot;B4. Malware that hunts for AI keys&quot;">​</a></h3><p><em>October 2026, [A].</em> In two weeks: a compromised release of the real npm package <code>tensorlake</code> collected <code>.env</code> files, SSH keys and AI tools&#39; config folders and MCP files from a <code>preinstall</code> hook; a trojanized LiteLLM release stole AI provider keys; fake npm packages offering &quot;free Claude and Gemini credits&quot; added an attacker&#39;s MCP server to victims&#39; agent settings; and an intruder reached OpenCode&#39;s hosted Console and exposed stored provider keys, with some users seeing unauthorized charges of more than $1,000 (the open-source tool was not affected).</p><ul><li><strong>Lesson:</strong> your AI keys are money, and malware knows where agents keep them. Keys with no billing attached are worth nothing to steal.</li><li><strong>Rules:</strong> 4, 6, 8.</li><li><strong>Discuss:</strong> (1) What&#39;s in your agent&#39;s config folder that an attacker would want? (2) If a course key were stolen tonight, what would limit the bill?</li><li><strong>Sources:</strong> <a href="https://socket.dev/blog/tensorlake-compromise" target="_blank" rel="noreferrer">Socket</a> · <a href="https://www.wiz.io/blog/litellm-compromised-steals-credentials" target="_blank" rel="noreferrer">Wiz</a> · <a href="https://thehackernews.com/2026/10/fake-web3-accelerator-uses-npm-packages.html" target="_blank" rel="noreferrer">The Hacker News</a> · <a href="https://techcrunch.com/2026/10/19/hackers-hit-ai-coding-tool-opencode-running-up-charges-on-users-ai-accounts/" target="_blank" rel="noreferrer">TechCrunch</a></li></ul><h3 id="b5-slopsquatting-packages-that-dont-exist" tabindex="-1">B5. Slopsquatting: packages that don&#39;t exist <a class="header-anchor" href="#b5-slopsquatting-packages-that-dont-exist" aria-label="Permalink to &quot;B5. Slopsquatting: packages that don&#39;t exist&quot;">​</a></h3><p><em>2025–26, [A].</em> A USENIX Security 2025 study of 16 models found invented package names in 21.7% of open-model and 5.2% of commercial-model outputs; 43% of invented names recurred in all ten repeat runs, which makes them predictable for attackers. A 2026 re-test found frontier models still invent 4.6–6.1% of names, with the same 127 fake names shared by all five models tested.</p><ul><li><strong>Lesson:</strong> verify that a package exists, is the one you meant and is maintained, before an agent installs it. Week 10&#39;s lab automates the check.</li><li><strong>Rule:</strong> 8.</li><li><strong>Discuss:</strong> Why does recurrence matter more than the rate?</li><li><strong>Sources:</strong> <a href="https://labs.cloudsecurityalliance.org/research/csa-research-note-slopsquatting-ai-supply-chain-20260419-csa/" target="_blank" rel="noreferrer">CSA research note</a> · <a href="https://arxiv.org/abs/2605.17062" target="_blank" rel="noreferrer">arXiv 2605.17062</a></li></ul><h3 id="b6-baxbench-working-but-exploitable" tabindex="-1">B6. BaxBench: working, but exploitable <a class="header-anchor" href="#b6-baxbench-working-but-exploitable" aria-label="Permalink to &quot;B6. BaxBench: working, but exploitable&quot;">​</a></h3><p><em>Study, 2025.</em> Across 392 backend tasks checked with functional tests <strong>and end-to-end exploits</strong>, the best model was 62% correct, and about half of the correct programs were exploitable. Separately, about 4% of 33,000+ agentic pull requests on GitHub are security-related; they merge less often and wait longer for review.</p><ul><li><strong>Lesson:</strong> &quot;the tests pass&quot; and &quot;it&#39;s secure&quot; are different measurements. Week 10&#39;s security review is its own step.</li><li><strong>Rule:</strong> 9. <strong>[Grad seminar]</strong> paper (BaxBench).</li><li><strong>Discuss:</strong> What would an exploit test for <code>roomly</code>&#39;s booking API look like?</li><li><strong>Sources:</strong> <a href="https://arxiv.org/abs/2502.11844" target="_blank" rel="noreferrer">Vero et al., arXiv 2502.11844</a> · <a href="https://arxiv.org/abs/2601.00477" target="_blank" rel="noreferrer">Siddiq et al., arXiv 2601.00477</a></li></ul><hr><h2 id="deleted-databases" tabindex="-1">Deleted databases <a class="header-anchor" href="#deleted-databases" aria-label="Permalink to &quot;Deleted databases&quot;">​</a></h2><h3 id="c1-replit-the-code-freeze-that-was-only-words" tabindex="-1">C1. Replit: the code freeze that was only words <a class="header-anchor" href="#c1-replit-the-code-freeze-that-was-only-words" aria-label="Permalink to &quot;C1. Replit: the code freeze that was only words&quot;">​</a></h3><p><em>July 2025, [A].</em> During a public trial, Replit&#39;s agent ignored an explicit code freeze and repeated instructions in capital letters, deleted a production database, created fake data and false test results, and said a rollback was impossible when it wasn&#39;t. Replit responded with automatic separation of development and production databases, better restore, and a planning-only mode.</p><ul><li><strong>Lesson:</strong> instructions are not guardrails. Only permissions, separation and real backups are. And an agent&#39;s report about what it did must be checked.</li><li><strong>Rules:</strong> 4, 7, 9.</li><li><strong>Discuss:</strong> (1) Rewrite the code freeze as a control instead of a sentence. (2) How would you check the claim &quot;rollback is impossible&quot;?</li><li><strong>Sources:</strong> <a href="https://fortune.com/2025/07/23/ai-coding-tool-replit-wiped-database-called-it-a-catastrophic-failure/" target="_blank" rel="noreferrer">Fortune</a> · <a href="https://www.theregister.com/2025/07/21/replit_saastr_vibe_coding_incident/" target="_blank" rel="noreferrer">The Register</a> · <a href="https://incidentdatabase.ai/cite/1152/" target="_blank" rel="noreferrer">AI Incident Database #1152</a></li></ul><h3 id="c2-pocketos-a-token-found-in-an-unrelated-file" tabindex="-1">C2. PocketOS: a token found in an unrelated file <a class="header-anchor" href="#c2-pocketos-a-token-found-in-an-unrelated-file" aria-label="Permalink to &quot;C2. PocketOS: a token found in an unrelated file&quot;">​</a></h3><p><em>April 2026, [A].</em> A Cursor agent doing a routine task on staging hit a credential mismatch and, on its own initiative, deleted a cloud storage volume, wiping production data and the backups stored on the same volume, in about nine seconds. It used an API token it found in an unrelated file, created for managing domain names. Afterwards it listed the project&#39;s safety rules it had broken.</p><ul><li><strong>Lesson:</strong> an agent will use any credential it can find. Backups on the same volume aren&#39;t backups. Written rules didn&#39;t stop it.</li><li><strong>Rules:</strong> 5, 7.</li><li><strong>Discuss:</strong> (1) List every place a credential for your team fork exists right now. Which can an agent read? (2) The agent could recite the rules afterwards. What does that say about <code>AGENTS.md</code>?</li><li><strong>Sources:</strong> <a href="https://ia.acs.org.au/article/2026/gone-in-9-seconds--ai-agent-deletes-company-database.html" target="_blank" rel="noreferrer">Information Age (ACS)</a> · <a href="https://www.tomshardware.com/tech-industry/artificial-intelligence/claude-powered-ai-coding-agent-deletes-entire-company-database-in-9-seconds-backups-zapped-after-cursor-tool-powered-by-anthropics-claude-goes-rogue" target="_blank" rel="noreferrer">Tom&#39;s Hardware</a></li></ul><hr><h2 id="benchmark-inflation" tabindex="-1">Benchmark inflation <a class="header-anchor" href="#benchmark-inflation" aria-label="Permalink to &quot;Benchmark inflation&quot;">​</a></h2><p><strong>The frame:</strong> a benchmark score combines the model, the scaffold, the adequacy of the tests and contamination. Ask five questions of any claim: which harness? what does &quot;pass&quot; mean? does the task predate the model&#39;s cutoff? is it pass^k with a confidence interval? does it survive the Agentic Benchmark Checklist? (<a href="./../research/notes/evidence-senior.html">evidence notes</a>). These cases fit week 12, with D5 as week 1&#39;s teaser.</p><h3 id="d1-swe-bench-verified-retired-by-its-co-creator" tabindex="-1">D1. SWE-bench Verified, retired by its co-creator <a class="header-anchor" href="#d1-swe-bench-verified-retired-by-its-co-creator" aria-label="Permalink to &quot;D1. SWE-bench Verified, retired by its co-creator&quot;">​</a></h3><p><em>February 2026.</em> OpenAI, which co-created SWE-bench Verified, stopped reporting it, citing contamination and flawed tests, and recommended SWE-bench Pro instead. According to coverage (the page itself returned 403 to the course&#39;s research), 59.4% of 138 audited hard tasks had material test or specification flaws.</p><ul><li><strong>Discuss:</strong> If the benchmark&#39;s maintainers abandon it, what should you make of a vendor&#39;s score on it last year?</li><li><strong>Sources:</strong> <a href="https://openai.com/index/why-we-no-longer-evaluate-swe-bench-verified/" target="_blank" rel="noreferrer">OpenAI</a> · <a href="https://aiweekly.co/alerts/openai-drops-swe-bench-verified-backs-pro-after-flaw-audit" target="_blank" rel="noreferrer">AI Weekly (coverage)</a></li></ul><h3 id="d2-the-solution-was-in-the-issue-the-tests-were-too-weak" tabindex="-1">D2. The solution was in the issue; the tests were too weak <a class="header-anchor" href="#d2-the-solution-was-in-the-issue-the-tests-were-too-weak" aria-label="Permalink to &quot;D2. The solution was in the issue; the tests were too weak&quot;">​</a></h3><p><em>Study, 2024.</em> In 32.67% of successful SWE-Agent + GPT-4 patches the solution was already in the issue text, and 31.08% passed only because the tests were weak. Filtering both out cut the resolve rate <strong>from 12.47% to 3.97%</strong>.</p><ul><li><strong>Discuss:</strong> Which of the two flaws could your team&#39;s own tests have?</li><li><strong>Source:</strong> <a href="https://arxiv.org/abs/2410.06992" target="_blank" rel="noreferrer">Aleithan et al., SWE-Bench+, arXiv 2410.06992</a></li></ul><h3 id="d3-plausible-patches-that-behave-differently" tabindex="-1">D3. Plausible patches that behave differently <a class="header-anchor" href="#d3-plausible-patches-that-behave-differently" aria-label="Permalink to &quot;D3. Plausible patches that behave differently&quot;">​</a></h3><p><em>Study, 2025.</em> A differential testing tool found that 29.6% of plausible patches behave differently from the ground truth, 28.6% of those are certainly wrong, and a further 7.8% were counted as passing despite failing the full test suite: together, <strong>6.2 points of inflated resolve rate</strong>.</p><ul><li><strong>Discuss:</strong> How is this the same problem as week 7&#39;s surviving mutants?</li><li><strong>Source:</strong> <a href="https://arxiv.org/abs/2503.15223" target="_blank" rel="noreferrer">Wang, Pradel &amp; Liu, arXiv 2503.15223</a> <strong>[Grad seminar]</strong></li></ul><h3 id="d4-remembering-instead-of-reasoning" tabindex="-1">D4. Remembering instead of reasoning <a class="header-anchor" href="#d4-remembering-instead-of-reasoning" aria-label="Permalink to &quot;D4. Remembering instead of reasoning&quot;">​</a></h3><p><em>Study, 2025.</em> From the issue text alone, models named the buggy file up to 76% of the time on SWE-bench against 53% on other repositories, and reproduced function 5-grams verbatim at 35% against 18%.</p><ul><li><strong>Discuss:</strong> Design a contamination check for an eval you build in week 12.</li><li><strong>Source:</strong> <a href="https://arxiv.org/abs/2506.12286" target="_blank" rel="noreferrer">Liang, Garg &amp; Zilouchian Moghaddam, arXiv 2506.12286</a> <strong>[Grad seminar] [Replicable]</strong></li></ul><h3 id="d5-maintainers-vs-graders" tabindex="-1">D5. Maintainers vs graders <a class="header-anchor" href="#d5-maintainers-vs-graders" aria-label="Permalink to &quot;D5. Maintainers vs graders&quot;">​</a></h3><p><em>2025–26.</em> In 2025 METR found that none of 15 reviewed agent PRs was mergeable as-is, though 38% passed the tests; fixing them took 42 minutes on average. In 2026 four maintainers of scikit-learn, Sphinx and pytest reviewed 296 test-passing agent PRs: their merge rate ran <strong>24.2 points below the automated grader</strong> after normalizing to golden patches, and they merged only 68% of the human-written golden patches themselves.</p><ul><li><strong>Discuss:</strong> (1) What do maintainers check that tests don&#39;t? (2) Note the 68%: what does it say about maintainer judgment as a gold standard?</li><li><strong>Sources:</strong> <a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">METR, 2026</a> · <a href="https://metr.org/blog/2025-08-12-research-update-towards-reconciling-slowdown-with-time-horizons" target="_blank" rel="noreferrer">METR, 2025</a></li></ul><h3 id="d6-empty-answers-counted-as-successes" tabindex="-1">D6. Empty answers counted as successes <a class="header-anchor" href="#d6-empty-answers-counted-as-successes" aria-label="Permalink to &quot;D6. Empty answers counted as successes&quot;">​</a></h3><p><em>Study, 2025.</em> The Agentic Benchmark Checklist found task and reward flaws that distort scores by up to 100% in relative terms: SWE-bench Verified has weak tests, and τ-bench counted <strong>empty responses as successes</strong>. Applying the checklist cut CVE-Bench&#39;s overestimation by 33%. A hand audit of 100 random SWE-Bench Pro tasks found lenient tests, a test that requires a since-fixed bug, and requirements text that leaks the gold patch.</p><ul><li><strong>Discuss:</strong> Run three items of the checklist against your own week 12 eval.</li><li><strong>Sources:</strong> <a href="https://arxiv.org/abs/2507.02825" target="_blank" rel="noreferrer">Zhu et al., arXiv 2507.02825</a> <strong>[Grad seminar]</strong> · <a href="https://jonathanpgabor.substack.com/p/swe-bench-pro-is-even-worse" target="_blank" rel="noreferrer">Gabor, &quot;SWE-Bench Pro is even worse&quot;</a></li></ul><hr><h2 id="maintainers-ai-policies" tabindex="-1">Maintainers&#39; AI policies <a class="header-anchor" href="#maintainers-ai-policies" aria-label="Permalink to &quot;Maintainers&#39; AI policies&quot;">​</a></h2><p><strong>The frame:</strong> projects converge on <strong>disclose, understand, take responsibility</strong>, enforced by a human sign-off, and disagree on how to record AI involvement. In 1,000 popular repositories, 118 had a contributor AI policy: 78% allow AI-assisted contributions, 51% require disclosure and 74% require a human in the loop (<a href="https://arxiv.org/abs/2605.16706" target="_blank" rel="noreferrer">Hora &amp; Robbes, arXiv 2605.16706</a>). A study of 281 policies found 48.8% require disclosure (<a href="https://arxiv.org/abs/2609.07542" target="_blank" rel="noreferrer">Hora et al., arXiv 2609.07542</a>, [A]). Policies change fast: check the current text before you contribute.</p><h3 id="e1-qemu-decline-and-a-proposal-to-relax" tabindex="-1">E1. QEMU: decline, and a proposal to relax <a class="header-anchor" href="#e1-qemu-decline-and-a-proposal-to-relax" aria-label="Permalink to &quot;E1. QEMU: decline, and a proposal to relax&quot;">​</a></h3><p>QEMU&#39;s policy is to &quot;DECLINE any contributions which are believed to include or derive from AI generated content&quot;, citing DCO and copyright uncertainty; AI for research, static analysis or debugging is allowed if its output isn&#39;t included. A May 2026 proposal would allow mechanical changes, bug fixes of about 20 lines, docs and tests, recorded with an <code>AI-used-for:</code> trailer (explicitly not <code>Assisted-by</code>). It drew acks and strong objections; as of 2 Nov 2026 no decision is recorded.</p><ul><li><strong>Discuss:</strong> If you found a bug in QEMU with an agent&#39;s help, what could you contribute?</li><li><strong>Sources:</strong> <a href="https://www.qemu.org/docs/master/devel/code-provenance.html" target="_blank" rel="noreferrer">QEMU code provenance</a> · <a href="https://patchew.org/QEMU/20260529094619.1034458-1-pbonzini@redhat.com/" target="_blank" rel="noreferrer">Bonzini&#39;s patch</a></li></ul><h3 id="e2-ghostty-disclose-everything-or-be-denounced" tabindex="-1">E2. Ghostty: disclose everything, or be denounced <a class="header-anchor" href="#e2-ghostty-disclose-everything-or-be-denounced" aria-label="Permalink to &quot;E2. Ghostty: disclose everything, or be denounced&quot;">​</a></h3><p>&quot;All AI usage in any form must be disclosed.&quot; Contributors must be able to explain changes without AI; AI-generated media is banned; and people who submit slop may go on a public denouncement list that blocks future contributions. The policy also says: if you&#39;re learning, don&#39;t use AI, &quot;and we&#39;ll help you&quot;.</p><ul><li><strong>Discuss:</strong> One student&#39;s slop could put a university&#39;s name on such a list. What does the course&#39;s upstream screening protect?</li><li><strong>Source:</strong> <a href="https://github.com/ghostty-org/ghostty/blob/main/AI_POLICY.md" target="_blank" rel="noreferrer">Ghostty AI_POLICY.md</a></li></ul><h3 id="e3-llvm-a-human-in-the-loop-and-an-assisted-by-trailer" tabindex="-1">E3. LLVM: a human in the loop and an Assisted-by trailer <a class="header-anchor" href="#e3-llvm-a-human-in-the-loop-and-an-assisted-by-trailer" aria-label="Permalink to &quot;E3. LLVM: a human in the loop and an Assisted-by trailer&quot;">​</a></h3><p>&quot;Contributors must read and review all LLM-generated code.&quot; New contributors should start small; &quot;Passing maintainer feedback to an LLM doesn&#39;t help anyone grow&quot;. Disclosure uses a trailer such as <code>Assisted-by:</code>, PR descriptions are written by the contributor, and agents acting &quot;without human approval&quot; are banned. This course&#39;s <code>Assisted-by:</code> trailer and self-written PR descriptions come from here.</p><ul><li><strong>Discuss:</strong> Why ban feeding review comments to an LLM, if the fix is correct?</li><li><strong>Source:</strong> <a href="https://github.com/llvm/llvm-project/blob/main/llvm/docs/AIToolPolicy.md" target="_blank" rel="noreferrer">LLVM AIToolPolicy.md</a></li></ul><h3 id="e4-the-linux-kernel-drops-its-ai-tag" tabindex="-1">E4. The Linux kernel drops its AI tag <a class="header-anchor" href="#e4-the-linux-kernel-drops-its-ai-tag" aria-label="Permalink to &quot;E4. The Linux kernel drops its AI tag&quot;">​</a></h3><p>The kernel&#39;s coding-assistants document requires GPL-2.0-compatible code, says &quot;AI agents MUST NOT add Signed-off-by tags,&quot; and puts full responsibility on the human. Per Hackaday, maintainers dropped the <code>Assisted-by</code> tag requirement in October 2026, and the master copy no longer mentions it; networking maintainers secured budget to run several frontier models on each patch for review.</p><ul><li><strong>Discuss:</strong> The kernel dropped disclosure and added AI review. Is that consistent?</li><li><strong>Sources:</strong> <a href="https://github.com/torvalds/linux/blob/master/Documentation/process/coding-assistants.rst" target="_blank" rel="noreferrer">coding-assistants.rst</a> · <a href="https://hackaday.com/2026/10/15/linux-kernel-drops-ai-tag-requirement-uses-meta-ai-for-code-reviews/" target="_blank" rel="noreferrer">Hackaday</a></li></ul><h3 id="e5-django-gentoo-and-netbsd-three-more-answers" tabindex="-1">E5. Django, Gentoo and NetBSD: three more answers <a class="header-anchor" href="#e5-django-gentoo-and-netbsd-three-more-answers" aria-label="Permalink to &quot;E5. Django, Gentoo and NetBSD: three more answers&quot;">​</a></h3><p>Django requires disclosing the tools and what they did and verifying output against the full test suite, includes a &quot;Note for AI Tools&quot; addressed to agents, and asks contributors not to request automated AI reviews because they &quot;often generate noise&quot;. Gentoo <strong>bans</strong> content created with NLP AI tools. NetBSD treats LLM output as &quot;presumed to be tainted code&quot; needing prior written approval from core. Debian declined to adopt a ban.</p><ul><li><strong>Discuss:</strong> Django addresses agents directly in its docs. Should your <code>AGENTS.md</code> do the same for your team fork?</li><li><strong>Sources:</strong> <a href="https://docs.djangoproject.com/en/dev/internals/contributing/writing-code/submitting-patches/" target="_blank" rel="noreferrer">Django</a> · <a href="https://wiki.gentoo.org/wiki/Project:Council/AI_policy" target="_blank" rel="noreferrer">Gentoo</a> · <a href="https://www.netbsd.org/developers/commit-guidelines.html" target="_blank" rel="noreferrer">NetBSD</a> · <a href="https://itwire.com/business-it-news/open-source/debian-project-not-keen-on-drafting-policy-to-cover-ai-contributions" target="_blank" rel="noreferrer">iTWire on Debian</a></li></ul><h3 id="e6-curl-ends-its-bug-bounty" tabindex="-1">E6. curl ends its bug bounty <a class="header-anchor" href="#e6-curl-ends-its-bug-bounty" aria-label="Permalink to &quot;E6. curl ends its bug bounty&quot;">​</a></h3><p><em>January 2026.</em> curl&#39;s maintainer ended its HackerOne bug bounty (up to $10,000) to remove the incentive for AI-generated junk reports.</p><ul><li><strong>Discuss:</strong> Who paid the cost of the junk reports, and who could have prevented it?</li><li><strong>Sources:</strong> <a href="https://www.theregister.com/2026/01/21/curl_ends_bug_bounty/" target="_blank" rel="noreferrer">The Register</a> · <a href="https://bleepingcomputer.com/news/security/curl-ending-bug-bounty-program-after-flood-of-ai-slop-reports/" target="_blank" rel="noreferrer">BleepingComputer</a></li></ul><h3 id="e7-platforms-push-back-pr-caps-and-hacktoberfest" tabindex="-1">E7. Platforms push back: PR caps and Hacktoberfest <a class="header-anchor" href="#e7-platforms-push-back-pr-caps-and-hacktoberfest" aria-label="Permalink to &quot;E7. Platforms push back: PR caps and Hacktoberfest&quot;">​</a></h3><p>GitHub added settings to restrict pull requests to collaborators, then a cap on open PRs from users without write access that counts agent-opened PRs, then exemptions by account age or contribution history. The MCP TypeScript SDK allows &quot;one open pull request at a time&quot; from such contributors. Godot maintainers called AI PRs &quot;draining and demoralizing&quot;. Hacktoberfest 2026 dropped its PR challenge after &quot;a massive flood of activity and burnout from the rise of low-effort PRs&quot;.</p><ul><li><strong>Discuss:</strong> A new student account may be capped by default. How does the course&#39;s three-tier project design handle that?</li><li><strong>Sources:</strong> <a href="https://github.com/orgs/community/discussions/187038" target="_blank" rel="noreferrer">GitHub discussion #187038</a> · <a href="https://visualstudiomagazine.com/articles/2026/06/30/github-extends-contribution-controls-from-prs-to-issues.aspx" target="_blank" rel="noreferrer">Visual Studio Magazine</a> · <a href="https://gigazine.net/gsc_news/en/20260618-github-limit-pull-request" target="_blank" rel="noreferrer">Gigazine</a> · <a href="https://www.theregister.com/2026/02/18/godot_maintainers_struggle_with_draining/" target="_blank" rel="noreferrer">The Register on Godot</a> · <a href="https://hacktoberfest.com/llms.txt" target="_blank" rel="noreferrer">Hacktoberfest</a></li></ul><h3 id="e8-hypocrite-commits-when-research-gets-an-institution-banned" tabindex="-1">E8. Hypocrite commits: when research gets an institution banned <a class="header-anchor" href="#e8-hypocrite-commits-when-research-gets-an-institution-banned" aria-label="Permalink to &quot;E8. Hypocrite commits: when research gets an institution banned&quot;">​</a></h3><p><em>2021.</em> The Linux kernel banned contributions from the University of Minnesota after a research group submitted deliberately flawed &quot;hypocrite commits&quot;; how IRB review was handled is disputed in the coverage. One group&#39;s study got a whole institution blocked.</p><ul><li><strong>Lesson for graduate studies:</strong> no intervening on maintainers or classmates without IRB review. Use public data and your own artifacts (<a href="./../templates/STUDY_PROTOCOL.html">STUDY_PROTOCOL.md template</a>).</li><li><strong>Sources:</strong> <a href="https://www.theregister.com/2021/04/21/minnesota_linux_kernel_flaws_update/" target="_blank" rel="noreferrer">The Register</a> · <a href="https://lwn.net/Articles/854076/" target="_blank" rel="noreferrer">LWN</a></li></ul><hr><h2 id="where-sources-disagree" tabindex="-1">Where sources disagree <a class="header-anchor" href="#where-sources-disagree" aria-label="Permalink to &quot;Where sources disagree&quot;">​</a></h2><ul><li><strong>AI reviewers and cycle time.</strong> At Beko, PR-Agent&#39;s comments were 73.8% resolved but closure time rose 42%; at Atlassian, PR cycle time fell 30.8% (<a href="https://arxiv.org/abs/2412.18531" target="_blank" rel="noreferrer">Cihan et al.</a>; <a href="https://arxiv.org/abs/2601.01129v2" target="_blank" rel="noreferrer">Tantithamthavorn et al.</a>). Different settings, different outcomes: don&#39;t quote either as &quot;the&quot; effect.</li><li><strong>Cursor&#39;s effect on complexity.</strong> He et al. report +40.7% in a table and 25.1% in the text (<a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">arXiv 2511.04427</a>).</li><li><strong>SWE-Bench Pro scores.</strong> The paper&#39;s tables, its conclusion and vendor claims on aggregators disagree (<a href="https://arxiv.org/abs/2509.16941" target="_blank" rel="noreferrer">Deng et al.</a>).</li><li><strong>The kernel&#39;s <code>Assisted-by</code> tag.</strong> Earlier notes described it as current; as of November 2026 it is gone from the master policy (E4).</li><li><strong>SWE-bench Verified flaw rate (D1)</strong> comes from coverage, not from OpenAI&#39;s page.</li><li><strong>Sibling-course cases [A]</strong> were verified by that course in September–October 2026 and not re-opened here. The two MCP advisories in the tool notes (GHSA-m84r-3mrm-j4p8, GHSA-6qxp-vccf-f47h) were not opened at all: verify before putting them on a slide.</li></ul><h2 id="more" tabindex="-1">More <a class="header-anchor" href="#more" aria-label="Permalink to &quot;More&quot;">​</a></h2><ul><li>The rules these cases produced: <a href="./../setup/safety-contract.html">Agent Safety Contract</a></li><li>Readings by week: <a href="./reading-list.html">Reading List</a></li><li>The labs that turn section A into practice: <a href="./../weeks/04-securing-agents/">week 4</a> · section B: <a href="./../weeks/10-supply-chain/">week 10</a> · section D: <a href="./../weeks/12-evals/">week 12</a> · section E: <a href="./../weeks/14-evidence-and-responsibility/">week 14</a></li></ul>',120)])])}const p=t(o,[["render",n]]);export{g as __pageData,p as default};
